import unittest
import flags


class TestParseBool(unittest.TestCase):
    def test_true_values(self):
        for val in ("true", "yes", "on", "1"):
            self.assertIs(flags.parse_bool(val), True)

    def test_false_values(self):
        for val in ("false", "no", "off", "0"):
            self.assertIs(flags.parse_bool(val), False)

    def test_case_insensitivity(self):
        for val in ("TRUE", "True", "tRuE", "YES", "Yes", "ON", "On"):
            self.assertIs(flags.parse_bool(val), True)
        for val in ("FALSE", "False", "fAlSe", "NO", "No", "OFF", "Off"):
            self.assertIs(flags.parse_bool(val), False)

    def test_surrounding_whitespace(self):
        for val in ("  true  ", "\tyes\n", "  on ", " 1 \t"):
            self.assertIs(flags.parse_bool(val), True)
        for val in ("  false  ", "\tno\n", "  off ", " 0 \t"):
            self.assertIs(flags.parse_bool(val), False)

    def test_empty_string(self):
        with self.assertRaises(ValueError):
            flags.parse_bool("")

    def test_whitespace_only(self):
        for val in (" ", "   ", "\t", "\n", " \t\n "):
            with self.assertRaises(ValueError):
                flags.parse_bool(val)

    def test_invalid_values(self):
        invalid_values = (
            "2",
            "-1",
            "t",
            "f",
            "y",
            "n",
            "tru",
            "fals",
            "true1",
            "false0",
            "null",
            "none",
            "undefined",
            "maybe",
        )
        for val in invalid_values:
            with self.assertRaises(ValueError):
                flags.parse_bool(val)


if __name__ == "__main__":
    unittest.main()

