        for val in ("  true  ", "\tyes\n", "  on ", " 1 \t"):
            self.assertIs(flags.parse_bool(val), True)
        for val in ("  false  ", "\tno\n", "  off ", " 0 \t"):
            self.assertIs(flags.parse_bool(val), False)

